-- Rename displayed branding, including rich text and dynamically created labels.
do
    local roots = { game:GetService("CoreGui"), game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui") }
    if type(gethui) == "function" then
        local ok, root = pcall(gethui)
        if ok and typeof(root) == "Instance" then
            table.insert(roots, root)
        end
    end
    local watched = setmetatable({}, { __mode = "k" })
    local function updateLabel(object)
        if not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then
            return
        end
        local text = object.Text
        local visible = text:gsub("<[^>]->", "")
        local normalized = visible:lower()
        local first, last = normalized:find("banana cat hub", 1, true)
        if not first then first, last = normalized:find("banana hub", 1, true) end
        if not first then first, last = normalized:find("binini hub", 1, true) end
        if first then
            -- Remove rich-text markup only on a label containing old branding.
            object.Text = visible:sub(1, first - 1) .. "Vip Hub" .. visible:sub(last + 1)
        end
    end
    local function watch(object)
        if watched[object] then return end
        if not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then return end
        watched[object] = true
        object:GetPropertyChangedSignal("Text"):Connect(function()
            updateLabel(object)
        end)
        updateLabel(object)
    end
    for _, root in ipairs(roots) do
        root.DescendantAdded:Connect(watch)
        for _, object in ipairs(root:GetDescendants()) do watch(object) end
    end
end

