        icon = assetLoader("Vip_Hub_Icon_v2.png")
        assert(type(icon) == "string" and #icon > 0, "Executor returned no image asset")
    end)
    if not ok then
        warn("[Vip Hub] Icon could not load: " .. tostring(iconError))
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Vip Hub icon error", Text = tostring(iconError), Duration = 20
            })
        end)
    else
        task.spawn(function()
            local imageIds = {}
            while task.wait(0.5) do
                pcall(function()
                    local roots = {game:GetService("CoreGui"), game.Players.LocalPlayer.PlayerGui}
                    if type(gethui) == "function" then table.insert(roots, gethui()) end
                    local hubGuis = {}
                    for _, root in ipairs(roots) do
                        for _, obj in ipairs(root:GetDescendants()) do
                            if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and obj.Text:find("Vip Hub", 1, true) then
                                local gui = obj:FindFirstAncestorOfClass("ScreenGui")
                                if not gui then
                                    gui = obj
                                    while gui.Parent and gui.Parent ~= root do gui = gui.Parent end
                                end
                                if gui then hubGuis[gui] = true end
                            end
                        end
                    end
                    for gui in pairs(hubGuis) do
                        for _, obj in ipairs(gui:GetDescendants()) do
                            if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                                local size = obj.AbsoluteSize
                                local square = size.X >= 20 and size.X <= 110 and math.abs(size.X-size.Y) <= 12
                                if square and obj.Image ~= "" and obj.Image ~= icon then imageIds[obj.Image] = true end
                                if square or imageIds[obj.Image] then
                                    obj.Image = icon
                                    obj.ImageColor3 = Color3.new(1,1,1)
                                    obj.ImageRectOffset = Vector2.zero
                                    obj.ImageRectSize = Vector2.zero
                                end
                            end
                        end
                    end
                    for _, root in ipairs(roots) do
                        for _, obj in ipairs(root:GetDescendants()) do
                            if (obj:IsA("ImageLabel") or obj:IsA("ImageButton")) and imageIds[obj.Image] then
                                obj.Image = icon
                                obj.ImageColor3 = Color3.new(1,1,1)
                                obj.ImageRectOffset = Vector2.zero
                                obj.ImageRectSize = Vector2.zero
                            end
                        end
                    end
                end)
            end
        end)
    end
    local watched = setmetatable({}, {__mode = "k"})
    local themed = setmetatable({}, {__mode = "k"})
    local function blue(color)
        local h, sat, value = color:ToHSV()
        if sat > 0.18 and h < 0.19 then
            return Color3.fromHSV(0.59, math.max(sat, 0.65), value)
        end
        if sat < 0.25 and value < 0.36 then
            return Color3.fromHSV(0.61, 0.65, math.max(value, 0.09))
        end
        return color
    end
    local function style(obj)
        if watched[obj] then return end
        watched[obj] = true
        local props = {}
        if obj:IsA("GuiObject") then
            props = {"BackgroundColor3", "BorderColor3"}
            if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                table.insert(props, "TextColor3")
            end
            if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                table.insert(props, "ImageColor3")
                local name = obj.Name:lower()
                local pos, size = obj.AbsolutePosition, obj.AbsoluteSize
                local parent = obj.Parent
                local top = parent and parent:IsA("GuiObject") and parent.AbsolutePosition.Y or pos.Y
                local headerIcon = size.X >= 28 and size.X <= 80 and math.abs(size.X-size.Y) < 8 and pos.Y-top < 48
                local dimensions = obj.Size
                local squareIcon = (size.X >= 28 and size.X <= 100 and math.abs(size.X-size.Y) <= 10)
                    or (dimensions.X.Scale == 0 and dimensions.Y.Scale == 0
                        and dimensions.X.Offset >= 28 and dimensions.X.Offset <= 100
                        and math.abs(dimensions.X.Offset-dimensions.Y.Offset) <= 10)
                if icon and (name:find("logo") or name:find("icon") or squareIcon) then
                    obj.Image = icon
                    obj.ImageColor3 = Color3.new(1,1,1)
                    obj.ImageRectOffset = Vector2.zero
                    obj.ImageRectSize = Vector2.zero
                end
            end
        elseif obj:IsA("UIStroke") then
            props = {"Color"}
        elseif obj:IsA("UIGradient") then
            local function gradient()
                local points = {}
                local changed = false
                for _, point in ipairs(obj.Color.Keypoints) do
                    local color = blue(point.Value)
                    changed = changed or color ~= point.Value
                    table.insert(points, ColorSequenceKeypoint.new(point.Time, color))
                end
                if changed then obj.Color = ColorSequence.new(points) end
            end
            obj:GetPropertyChangedSignal("Color"):Connect(gradient)
            gradient()
        end
        for _, property in ipairs(props) do
            local function update()
                local old = obj[property]
                local color = blue(old)
                if color ~= old then obj[property] = color end
            end
            obj:GetPropertyChangedSignal(property):Connect(update)
            update()
        end
    end
    local function theme(gui)
        if themed[gui] then return end
        themed[gui] = true
        for _, obj in ipairs(gui:GetDescendants()) do pcall(style, obj) end
        gui.DescendantAdded:Connect(function(obj) task.defer(function() pcall(style, obj) end) end)
    end
    -- Identify only the hub's GUI, leaving the game's own interface alone.
    for attempt = 1, 60 do
        local roots = {game:GetService("CoreGui"), game.Players.LocalPlayer:WaitForChild("PlayerGui")}
        if type(gethui) == "function" then
            local ok, root = pcall(gethui)
            if ok and typeof(root) == "Instance" then table.insert(roots, root) end
        end
        for _, root in ipairs(roots) do
            for _, obj in ipairs(root:GetDescendants()) do
                if obj:IsA("TextLabel") or obj:IsA("TextButton") then
                    if obj.Text:find("Vip Hub", 1, true) then
                        local gui = obj:FindFirstAncestorOfClass("ScreenGui")
                                if not gui then
                                    gui = obj
                                    while gui.Parent and gui.Parent ~= root do gui = gui.Parent end
                                end
                        if gui then theme(gui) end
                    end
                end
            end
        end
        task.wait(1)
    end
end)
-- Apply Vip Hub branding to the separately downloaded UI library.
