	for l, S in b, s, X do
		if
			S.Name == "Rock"
			and (S:FindFirstChild("VFXLayer"))
			and (S.VFXLayer:FindFirstChild("Specs"))
			and S.VFXLayer.Specs.Enabled
		then
			l = t:DistanceFromCharacter(S.WorldPivot.Position)
			if g > l then
				g, R = l, S
			end
		end
	end
	return R
end
