		if R:IsA("MeshPart") and R.MeshId == "rbxassetid://15672470777" and math.floor(R.Position.Y) == 86 then
			b[5] = R.Position
		end
		if R:IsA("MeshPart") and R.MeshId == "rbxassetid://5159878936" and math.floor(R.Position.Y) == 261 then
