			if
				g.Name ~= "Template"
					and g.Title.TextColor3 == Color3.new(1, 1, 1)
					and g.Cooldown.Size == UDim2.new(0, 0, 1, -1)
				or g.Cooldown.Size == UDim2.new(1, 0, 1, -1)
