			spawn(function()
				while Settings["Auto Find Prehistoric Island"] and (wait(0.1)) do
					pcall(function()
						AutoFindPrehistoric()
					end)
				end
			end)
		end
		SaveSettings("Auto Find Prehistoric Island", g)
	end
